/**
 * Applies pending database migrations (db/migrations, generated by `npm run db:generate`).
 *
 * Runs as Railway's pre-deploy command (`npm run db:migrate`): a deploy only goes live after
 * its migrations succeed, and a failed migration stops the deploy instead of starting a
 * server against the wrong schema.
 *
 * Safe to run repeatedly (applied migrations are skipped) and concurrently: a Postgres
 * advisory lock makes a second runner wait for the first.
 *
 * Usage:
 *   npm run db:migrate                 # uses DATABASE_URL (.env locally)
 *   DATABASE_URL=pglite://.pglite npm run db:migrate
 */
import 'dotenv/config';
import { sql } from 'drizzle-orm';
import { openDatabase, isDbConfigured } from '../lib/db.js';
import { MIGRATIONS_DIR, MIGRATION_LOCK_ID } from '../db/migrations.js';

if (!isDbConfigured()) {
   console.error('DATABASE_URL is not set — nothing to migrate. See docs/database.md.');
   process.exit(1);
}

const url = process.env.DATABASE_URL.trim();
const handle = await openDatabase(url, { pool: { max: 1, statement_timeout: 0 } }); // migrations may be slow
const { db, kind } = handle;
const started = Date.now();

try {
   if (kind === 'postgres') {
      await db.execute(sql`select pg_advisory_lock(${MIGRATION_LOCK_ID})`);
   }
   const { migrate } = await import(kind === 'postgres' ? 'drizzle-orm/node-postgres/migrator' : 'drizzle-orm/pglite/migrator');
   await migrate(db, { migrationsFolder: MIGRATIONS_DIR });
   console.log(`[db:migrate] up to date (${kind}, ${Date.now() - started} ms)`);
} catch (err) {
   console.error('[db:migrate] failed:', err.message);
   process.exitCode = 1;
} finally {
   if (kind === 'postgres') {
      await db.execute(sql`select pg_advisory_unlock(${MIGRATION_LOCK_ID})`).catch(() => {});
   }
   await handle.close();
}
